import { COMMON_ICONS } from "./material/common";
import type { IconData } from "./material/types";

/* Custom icons: your own SVGs, built in by tools/icons/build.py. Each is the inner markup of a
   24×24 SVG, cleaned by the build (shapes only, drawn in currentColor), so it's safe to insert. */
/* @icons:start generated by tools/icons/build.py from your icon SVGs; edit the SVGs, not this */
export const ICONS: Record<string, string> = {};
/* @icons:end */

// @icons:start generated by tools/icons/build.py
/** Names of the custom icons (tools/icons/build.py). Empty (never) until you add some. */
export type CustomIconName = never;
// @icons:end

/** Names of your custom icons, sorted. */
export const customIcons = Object.freeze(Object.keys(ICONS).sort()) as readonly CustomIconName[];

export function hasIcon(name: unknown): name is string {
  return typeof name === "string" && Object.prototype.hasOwnProperty.call(ICONS, name);
}

/* Material Symbols by name: the everyday set (src/material/common.ts) and any icon a project registers. */
const NAMED = new Map<string, IconData>(COMMON_ICONS.map((i) => [i.name, i]));

/** Makes Material Symbols work by name (`<Icon name="rocket_launch" />`, `leftIcon="rocket_launch"`).
 * Pass icons, or a whole module: `registerIcons(RocketLaunch, Pets)` or `registerIcons(await import("serupa-ds/icons"))`. */
export function registerIcons(...icons: Array<IconData | Readonly<Record<string, IconData>>>): void {
  for (const x of icons) {
    if (isIconData(x)) NAMED.set(x.name, x);
    else for (const v of Object.values(x)) if (isIconData(v)) NAMED.set(v.name, v);
  }
}

/** The Material Symbol registered under a name, if any. */
export function getIcon(name: string): IconData | undefined {
  return NAMED.get(name);
}

export function isIconData(x: unknown): x is IconData {
  return !!x && typeof x === "object" && typeof (x as IconData).name === "string" && typeof (x as IconData).d === "string";
}
